typedef unsigned char uint8;
typedef unsigned int uint32;

void *operator new(unsigned int, unsigned int, const char *, int);
#define NEW new(0, 0, __FILE__, __LINE__)

class stringx {
    char data[16];
public:
    stringx();
    stringx(const char *, int = -1);
    stringx(const stringx &);
    ~stringx();
};

class color32 {
public:
    union {
        struct { uint8 b, g, r, a; } c;
        uint32 i;
    };

    color32(uint8 r, uint8 g, uint8 b, uint8 a = 255) {
        c.b = b;
        c.g = g;
        c.r = r;
        c.a = a;
    }
};

class Font {
public:
    enum HORIZJUST { HORIZJUST_LEFT, HORIZJUST_CENTER, HORIZJUST_RIGHT };
    enum VERTJUST { VERTJUST_TOP, VERTJUST_CENTER, VERTJUST_BOTTOM };
};

class TextString {
protected:
    void *font;
    stringx text;
    float x;
    float y;
    int z;
    Font::HORIZJUST hJustify;
    Font::VERTJUST vJustify;
    bool even_number_spacing;
    int fade;
    float fade_alpha;
    float fade_timer;
    float scale;
    float button_scale;
    bool override_alpha;
public:
    bool checkTime;
    float time;

    TextString(void *f, stringx t, float x1, float y1, int z1, float s,
               Font::HORIZJUST horizJust, Font::VERTJUST vertJust, color32 col) {
        cons(f, t, x1, y1, z1, s, horizJust, vertJust, false, col);
    }
    virtual ~TextString();
    virtual void cons(void *, stringx, float, float, int, float,
                      Font::HORIZJUST, Font::VERTJUST, bool, color32);
};

class IGOWidget {
protected:
    bool display;
public:
    IGOWidget();
    virtual ~IGOWidget();
};

class PanelQuad;

class MeterChallengeWidget : public IGOWidget {
    PanelQuad *objectRoot;
    TextString *Text;
    float hiliteTime;
    float fade;
    int fadeDir;
public:
    MeterChallengeWidget();
    virtual ~MeterChallengeWidget();
};

MeterChallengeWidget::MeterChallengeWidget()
{
	objectRoot = NULL;

	Text = NEW TextString(NULL, "0", 516, 104, 10, 0.68f, Font::HORIZJUST_RIGHT, Font::VERTJUST_BOTTOM, color32(255, 255, 255, 255));

	fade = 0.0f;
	fadeDir = -1;

	display = false;
}
